#include<bits/stdc++.h>
#define int long long
using namespace std;
int a[222222],s[222222];
int n,k,ans;
void dfs(int p,int mn,int o){
	if(p>=n){
		if(o==k){
			ans=max(ans,mn);
		}
		return ;
	}else if(o>k||o+(n-p)<k){
		return ;
	}else{
		for(int i=p+1;i<=n;i++){
			dfs(i,min(mn,s[i]-s[p]),o+1);

		}
	}
}

signed main(){
	ios::sync_with_stdio(0);cin.tie(0);cout.tie(0);
	cin>>n>>k;
	for(int i=1;i<=n;i++){
		cin>>a[i];
		s[i]=s[i-1]+a[i];
	}
	dfs(0,INT_MAX,0);
	cout<<ans;
    return 0;
}
